	@Test
	void admissionFailureReleasesPreviouslyAdmittedCandidates() {
		IOException admissionFailure = new IOException("later strategy could not inspect the source");
		AtomicInteger released = new AtomicInteger();
		AtomicInteger opened = new AtomicInteger();
		LmdbNativeCandidate<String> first = candidate("first", 1D, () -> {
			opened.incrementAndGet();
			return "first";
		}, released::incrementAndGet);
		LmdbNativeStrategy<Void, String> failing = LmdbNativeStrategy.of(LmdbNativeDecisionPoint.ROW,
				"failedAdmission", context -> {
					throw admissionFailure;
				});
		LmdbNativeDispatchLoop<Void, String> loop = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				List.of(strategy(first), failing), null);

		Throwable failure = catchThrowable(() -> loop.dispatch(null));

		assertAll(() -> assertThat(failure).isSameAs(admissionFailure),
				() -> assertThat(released).hasValue(1),
				() -> assertThat(opened).hasValue(0));
	}

