		AtomicInteger rivalReleases = new AtomicInteger();
		AtomicInteger rivalOpens = new AtomicInteger();
		LmdbNativeCandidate<String> selected = candidate("selected", 1D, () -> {
			throw openingFailure;
		}, () -> {
			selectedReleases.incrementAndGet();
			throw cleanupFailure;
		});
		LmdbNativeCandidate<String> rival = candidate("rival", 100D, () -> {
			rivalOpens.incrementAndGet();
			return "rival";
		}, rivalReleases::incrementAndGet);
		LmdbNativeDispatchLoop<Void, String> loop = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				List.of(strategy(selected), strategy(rival)), null);

