		LmdbNativeCandidate<String> selected = candidate("selected", 1D, () -> "selected",
				selectedReleases::incrementAndGet);
		LmdbNativeCandidate<String> failed = candidate("failed", 2D, () -> "failed", () -> {
			failedReleases.incrementAndGet();
			throw cleanupFailure;
		});
		LmdbNativeCandidate<String> last = candidate("last", 3D, () -> "last", lastReleases::incrementAndGet);
		LmdbNativeDispatchLoop<Void, String> loop = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				List.of(strategy(selected), strategy(failed), strategy(last)), null);

