	@Test
	void aCancellationSingletonCannotHideALaterRealCleanupFailure() {
		IllegalStateException cleanupFailure = new IllegalStateException("real cleanup failure");
		AtomicInteger selectedReleases = new AtomicInteger();
		var selected = candidate("selected", 1D, () -> "selected", selectedReleases::incrementAndGet);
		var cancelled = candidate("cancelled", 2D, () -> "cancelled",
				() -> {
					throw KernelCancelledException.INSTANCE;
				});
		var failed = candidate("failed", 3D, () -> "failed", () -> {
			throw cleanupFailure;
		});
		var loop = new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				List.of(strategy(selected), strategy(cancelled), strategy(failed)), null);

		Throwable failure = catchThrowable(() -> loop.quotedChoice(null));

		assertAll(() -> assertThat(failure).isSameAs(cleanupFailure),
				() -> assertThat(selectedReleases).hasValue(1),
				() -> assertThat(cleanupFailure.getSuppressed()).contains(KernelCancelledException.INSTANCE),
				() -> assertThat(KernelCancelledException.INSTANCE.getSuppressed()).isEmpty());
	}

